User stories:
[{"id": "US1", "description": "Jako Pacjent chcę zarejestrować się przez OAuth (Google/Facebook) lub formularz z 3 polami (imię, email, hasło) w czasie poniżej 2 minut, aby szybko uzyskać dostęp do systemu rezerwacji bez zbędnych kroków weryfikacji."}, {"id": "US2", "description": "Jako Pacjent chcę przeglądać dostępne terminy u specjalistów z filtrowaniem po specjalizacji i dacie, z aktualizacją w czasie rzeczywistym bez przeładowania strony, aby szybko znaleźć odpowiedni termin wizyty."}, {"id": "US3", "description": "Jako Pacjent chcę zarezerwować wizytę w maksymalnie 3 krokach (wybór terminu, potwierdzenie danych, finalizacja) z natychmiastowym potwierdzeniem, aby proces był szybki i nie wymagał zbędnych działań."}, {"id": "US4", "description": "Jako Pacjent chcę anulować rezerwację jednym przyciskiem z opcjonalnym polem komentarza (nie wymaganym), aby móc łatwo zrezygnować z wizyty, przy czym system poinformuje mnie o ograniczeniu czasowym anulowania (domyślnie 24h przed wizytą)."}, {"id": "US5", "description": "Jako Pacjent chcę otrzymywać automatyczne potwierdzenia rezerwacji i przypomnienia przed wizytą (email/SMS), aby nie zapomnieć o zaplanowanej wizycie i być informowany o wszelkich zmianach."}, {"id": "US6", "description": "Jako Pacjent chcę mieć możliwość włączenia MFA na swoim koncie jako opcji opt-in, aby zwiększyć bezpieczeństwo bez obowiązku korzystania z tej funkcji przy każdym logowaniu."}, {"id": "US7", "description": "Jako Specjalista chcę zarządzać własnym grafikiem (dodawać, modyfikować i usuwać sloty czasowe) przez intuicyjny interfejs kalendarza, aby efektywnie kontrolować swoją dostępność dla pacjentów."}, {"id": "US8", "description": "Jako Specjalista chcę być powiadamiany o każdej nowej rezerwacji, anulowaniu oraz chcę móc zaproponować alternatywny termin przy modyfikacji slotu z istniejącą rezerwacją, aby utrzymać ciągłość obsługi pacjentów."}, {"id": "US9", "description": "Jako Specjalista chcę logować się z obowiązkowym MFA, aby moje konto i dane moich pacjentów były chronione przed nieautoryzowanym dostępem, akceptując że jest to wymóg bezpieczeństwa niezbędny dla ochrony danych medycznych."}, {"id": "US10", "description": "Jako Specjalista chcę mieć dostęp do historii płatności i faktur związanych z moją subskrypcją lub prowizjami od rezerwacji, aby móc rozliczać swoją działalność na platformie."}, {"id": "US11", "description": "Jako Administrator chcę ręcznie zatwierdzać wyjątki od konfliktów rezerwacji (np. wizyty grupowe) z obowiązkowym uzasadnieniem rejestrowanym w logu audytowym, aby zachować kontrolę nad przypadkami specjalnymi przy pełnej audytowalności."}, {"id": "US12", "description": "Jako Administrator chcę mieć dostęp do dashboardu biznesowego z kluczowymi metrykami (liczba rezerwacji, przychody, wskaźnik anulowań, aktywni użytkownicy) odświeżanymi co godzinę i eksportowalnymi do CSV, aby monitorować kondycję platformy od pierwszego dnia."}, {"id": "US13", "description": "Jako Administrator chcę przeglądać niemodyfikowalne logi audytowe wszystkich krytycznych operacji (rezerwacje, anulowania, zmiany grafiku, logowania, zmiany uprawnień) z możliwością filtrowania, aby wykrywać anomalie i przeprowadzać analizę incydentów bezpieczeństwa."}, {"id": "US14", "description": "Jako Administrator chcę konfigurować limit czasowy anulowania rezerwacji przez pacjenta (domyślnie 24h) oraz zarządzać rolami i uprawnieniami użytkowników, aby dostosować polityki systemu do potrzeb biznesowych przy zachowaniu kontroli dostępu."}, {"id": "US15", "description": "Jako Administrator chcę otrzymywać alerty bezpieczeństwa o anomaliach (wielokrotne nieudane logowania, masowe anulowania, podejrzane wzorce dostępu) z automatyczną blokadą konta po 5 nieudanych próbach logowania, aby szybko reagować na potencjalne zagrożenia."}, {"id": "US16", "description": "Jako Deweloper chcę mieć izolowane środowisko testowe z zanonimizowanymi danymi, automatycznymi testami regresji uruchamianymi przy każdym merge oraz mechanizmem rollback w ciągu 30 minut, aby zapewnić stabilność wdrożeń i możliwość szybkiej reakcji na błędy produkcyjne."}, {"id": "US17", "description": "Jako Pacjent chcę mieć możliwość usunięcia swojego konta i wszystkich powiązanych danych osobowych (prawo do bycia zapomnianym zgodnie z RODO) oraz eksportu swoich danych, aby mieć pełną kontrolę nad swoimi informacjami przechowywanymi w systemie."}]

