{
  "proposals": [
    {
      "proposal": "Skrócenie maksymalnego czasu sesji dla Pacjentów z 30 dni do 7 dni (sliding session) oraz dodanie wymogu re-autentykacji przy operacjach wrażliwych (anulowanie rezerwacji, zmiana danych profilu, żądanie RODO).",
      "rationale": "Sesja 30-dniowa drastycznie zwiększa okno ataku przy kradzieży tokenu. Dane medyczne i osobowe Pacjentów są wrażliwe – skrócenie do 7 dni przy zachowaniu sliding session minimalizuje ryzyko przy akceptowalnym wpływie na UX. Re-autentykacja przy operacjach wrażliwych to dodatkowa warstwa ochrony bez pełnego MFA.",
      "affected_requirements": ["FR16", "NFR15"]
    },
    {
      "proposal": "Dodanie do FR16 i NFR8 wymogu weryfikacji nowych haseł względem baz wycieków (np. HaveIBeenPwned API) przy rejestracji i zmianie hasła, jako zastępstwo dla rotacji co 90 dni. Hasło znalezione w bazie wycieków musi być odrzucone z komunikatem w języku naturalnym.",
      "rationale": "Rotacja co 90 dni jest trudna do wyegzekwowania i kosztowna UX-owo. Weryfikacja względem baz wycieków jest skuteczniejszą mitigacją credential stuffing przy minimalnym wpływie na UX i koszty. Eliminuje ryzyko używania skompromitowanych haseł bez wymuszania częstej rotacji.",
      "affected_requirements": ["FR16", "NFR8"]
    },
    {
      "proposal": "Dodanie do FR9 lub jako nowe wymaganie NFR formalnego wymogu przeprowadzenia testu penetracyjnego przed pierwszym wdrożeniem produkcyjnym oraz cyklicznie co 12 miesięcy. Wyniki pen-testu muszą być udokumentowane, a krytyczne i wysokie podatności usunięte przed wdrożeniem.",
      "rationale": "System przetwarza dane medyczne i płatnicze. Bez pen-testów podatności mogą pozostać niewykryte mimo poprawnej implementacji wymagań. Jeden pen-test przed MVP i coroczne testy to minimum dla systemu tej klasy – koszt jest akceptowalny w kontekście ryzyka prawnego (RODO, dane medyczne).",
      "affected_requirements": ["FR9", "NFR4"]
    }
  ]
