    },
    {
      "id": "AC7",
      "given": "Zalogowany Specjalista próbuje zmodyfikować termin z istniejącą rezerwacją Pacjenta",
      "when": "zatwierdza zmianę po jawnym potwierdzeniu",
      "then": "system zapisuje zmianę, automatycznie wysyła powiadomienie do Pacjenta i loguje operację w logu audytowym"
